INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66451363', 66451363, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Penyusunan Dokumen Pelaksanaan Pencapaian Tujuan Pembangunan Berkelanjutan/SDGs untuk Pilar Ekonomi Tujuan 7, Tujuan 8 dan Tujuan 9', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 141500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Konsultan Penyusunan Dokumen Analisis Pilar Pembangunan Ekonomi Tujuan 7, 8 dan 9 dilakukan dengan tujuan untuk tujuan untuk membantu pelaksanaan Kegiatan Koordinasi Pelaksanaan Pencapaian Sustainable Development Goals (SDGs) khususnya dalam bidang pilar pembangunan ekonomi tujuan 7, 8 dan 9.', '"a. Membantu penyusunan Rancangan Peraturan Presiden tentang Pelaksanaan Pencapaian Tujuan Pembangunan Berkelanjutan; b. Membantu penyusunan dan penyiapan draf awal pemutakhiran Rencana Aksi Nasional (RAN) TPB/SDGs 2025-2030 untuk pilar ekonomi terutama Tujuan 7, Tujuan 8 dan Tujuan 9; c. Membantu pemutakhiran draf Metadata Indikator TPB/SDGs Pilar Ekonomi terutama Tujuan 7, Tujuan 8 dan Tujuan 9; d. Menyiapkan draf awal analisis capaian Rencana Aksi Nasional (RAN) dan Rencana Aksi Daerah (RAD) untuk Pilar Ekonomi bagi pemerintah dan nonpemerintah terutama Tujuan 7, Tujuan 8 dan Tujuan 9; e. Menyiapkan pelaksanaan dan pelaporan SDGs Annual Conference dan SDGs Action Award 2026 f. Mendukung penugasan Manajer Pilar Ekonomi dalam melaksanakan penugasan lainnya di Sekretariat Nasional TPB/SDGs sesuai arahan Koordinator Tim Ahli.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2784919);
