INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66451374', 66451374, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Asisten Manager Pilar Pembangunan Lingkungan Bidang Monev pada Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 315000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Pengadaan Konsultan Penyusunan Dokumen Analisis Pilar Pembangunan Ekonomi Tujuan 7, 8 dan 9 dilakukan dengan tujuan untuk tujuan untuk membantu pelaksanaan Kegiatan Koordinasi Pelaksanaan Pencapaian Sustainable Development Goals (SDGs) khususnya dalam bidang pilar pembangunan ekonomi tujuan 7, 8 dan 9.', 'a. Menyusun dokumen legal aspek pelaksanaan SDGs (Draft surat Edaran Bersama Menteri, Peraturan Menteri PPN/Kepala Bappenas, SK Menteri PPN/Kepala Bappenas, dll); b. Menyusun informasi dan database indikator Pilar Pembangunan Lingkungan, serta ketersediaan sumber datanya, khususnya untuk isu air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); c. Menyusun indikator yang dikembangkan serta pembaharuan indikator yang disesuaikan dengan indikator global dalam Metadata Pilar Pembangunan Lingkungan, khususnya untuk air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); d. Menyusun Rencana Aksi Nasional (RAN) TPB/SDGs 2025-2029 dan mendukung koordinasi intensif unit kerja terkait dengan Tim Koordinasi Nasional TPB/SDGs yang meliputi pemerintah dan non-pemerintah, khususnya dalam ruang lingkup air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); e. Berkoordinasi dalam persiapan dan pelaksanaan SDGs Action Award dan Annual Conference 2026; f. Menyusun Laporan Tahunan Pelaksanaan TPB/SDGs, khususnya terkait air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); g. Fasilitasi provinsi terkait Penyusunan Rencana Aksi Daerah Tujuan Pembangunan Berkelanjutan (RAD TPB/SDGs), khususnya dalam ruang lingkup air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); h. Fasilitasi kepada Organisasi non Pemerintah terkait Penyusunan Rencana Aksi Daerah TPB/SDGs, khususnya dalam ruang lingkup air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); i. Fasilitasi kepada Organisasi non pemerintah terkait dengan penyusunan pemantauan, evaluasi, dan pelaporan pelaksanaan pencapaian TPB/SDGs, khususnya dalam ruang lingkup air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); j. Menyusun materi presentasi, laporan dan intervensi untuk pertemuan/workshop/seminar dalam rangka Pelaksanaan TPB/SDGs di dalam negeri maupun di tingkat internasional, khususnya terkait air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); k. Menyusun mekanisme diseminasi informasi terkait TPB/SDGs kepada berbagai pemangku kepentingan (Pemerintah, DPR, pihak swasta, filantropi, CSOs, media, akademisi, baik di tingkat nasional maupun daerah), dengan menggunakan data indikator-indikator Tujuan air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); l. Bekerjasama dengan bagian monitoring dan evaluasi (monev) dalam penyusunan pedoman monev TPB/SDGs dan SDGs dashboard, khususnya dalam ruang lingkup Pilar Pembangunan Lingkungan terkait air bersih dan sanitasi layak (Goal 6), Kota dan permukiman yang berkelanjutan (Goal 11), Konsumsi dan Produksi Berkelanjutan (Goal 12) perubahan iklim (Goal 13), Ekosistem Lautan (Goal 14) dan Ekosistem Daratan (Goal 15); m. Bekerjasama dengan berbagai pemangku kepentingan dalam menindaklanjuti Nota Kesepahaman yang telah ditandatangani bersama mitra pembangunan, seperti dengan GRI, UNICEF, dll; n. Pelaksanaan penugasan lainnya di Sekretariat TPB/SDGs, sesuai arahan Ketua Tim Pelaksana TPB/SDGs dan atau Kepala Sekretariat TPB/SDGs', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2786105);
